import { useCallback, useEffect, useState } from "react";
import type { FormEvent } from "react";
import { api, petDocumentContentPath, receiptContentPath, type CalendarEvent, type CalendarEventInput, type Expense, type ExpenseSummary, type LabResult, type MedicalRecord, type MedicalRecordType, type MedicationRestockPreview, type Pet, type PetBudget, type PetDashboard, type PetDocument, type PetExpenseSummary, type PetMedication, type PetTimelineItem, type Receipt, type RelationshipSet, type Reminder, type ReminderRules, type ShoppingItem, type ShoppingList, type Vaccination, type WeightEntry } from "../api";
import { amountInputValue, centsFromAmountInput, currentMonth, euros, eventClock, eventDay, eventInstants, localInputValue } from "../format";

export function Pets({ pets, events=[], reminders=[], reminderRules, busy, run }: { pets: Pet[];events?:CalendarEvent[];reminders?:Reminder[];reminderRules?:ReminderRules|null; busy: boolean; run: (task: () => Promise<unknown>, success: string) => Promise<void> }) {
  const active = pets.filter((pet) => pet.active);
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = event.currentTarget; const data = new FormData(form);
    await run(() => api.addPet({ name: String(data.get("name")), species: String(data.get("species")), breed: String(data.get("breed")), birthDate: String(data.get("birthDate")) || undefined, approximateBirthDate: data.get("approximateBirthDate") === "on", sex: String(data.get("sex")) as Pet["sex"], microchipNumber: String(data.get("microchipNumber")) || undefined, color: String(data.get("color")), insurance: String(data.get("insurance")), insuranceNumber: String(data.get("insuranceNumber")), veterinarian: String(data.get("veterinarian")), notes: "" }), "Tier angelegt"); form.reset();
  }
  function toggle(pet: Pet) {
    return run(() => api.updatePet(pet.id, { name: pet.name, species: pet.species, breed: pet.breed, birthDate: pet.birthDate, approximateBirthDate: pet.approximateBirthDate, sex: pet.sex, microchipNumber: pet.microchipNumber, color: pet.color, insurance: pet.insurance, insuranceNumber: pet.insuranceNumber, veterinarian: pet.veterinarian, notes: pet.notes, active: !pet.active }), pet.active ? "Tier archiviert" : "Tier wieder aktiviert");
  }
  async function saveRules(event:FormEvent<HTMLFormElement>){event.preventDefault();const raw=String(new FormData(event.currentTarget).get("leadDays"));const leadDays=raw.split(",").map((value)=>Number(value.trim())).filter((value)=>Number.isInteger(value));await run(()=>api.saveReminderRules({leadDays}),"Erinnerungsstufen gespeichert")}
  function appointmentFrom(item:Reminder){const startsAt=new Date(`${item.dueDate}T09:00:00`);const endsAt=new Date(startsAt.getTime()+60*60*1000);return run(()=>api.createReminderAppointment(item.sourceId,{title:`Impftermin: ${pets.find((pet)=>pet.id===item.petId)?.name??"Tier"}`,startsAt:startsAt.toISOString(),endsAt:endsAt.toISOString(),visibility:"shared"}),"Tiertermin angelegt")}
  return <><section className="hero"><div><p className="eyebrow">Eure Tiere</p><h1>Haustiere</h1><p>Stammdaten als Grundlage für Akte, Impfungen und Termine.</p></div><div className="hero-stat"><strong>{active.length}</strong><span>aktiv</span></div></section><section className="card reminder-card"><h2>Erinnerungen</h2>{reminders.length>0?<ul>{reminders.map((item)=><li key={item.id}><strong>{item.title}</strong><small>{pets.find((pet)=>pet.id===item.petId)?.name??"Tier"} · {item.dueDate} · Stufe {item.leadDays} Tage</small>{item.kind==="vaccination"&&<button disabled={busy} onClick={()=>void appointmentFrom(item)}>Termin um 09:00 anlegen</button>}</li>)}</ul>:<p>Heute ist keine konfigurierte Erinnerungsstufe erreicht.</p>}<form className="medical-form" onSubmit={saveRules}><label>Vorlauftage, kommasepariert<input name="leadDays" key={reminderRules?.leadDays.join(",")} defaultValue={reminderRules?.leadDays.join(", ")??"30, 7, 1"} required pattern="[0-9 ,]+"/></label><button disabled={busy}>Stufen speichern</button><small>1 bis 10 eindeutige Werte von 0 bis 366. Berechnung nur beim Öffnen; keine Nachrichten.</small></form></section>
    <div className="layout"><form className="card form-card" onSubmit={submit}><h2>Tier anlegen</h2><label>Name<input name="name" required maxLength={120} placeholder="z. B. Momo" /></label><div className="split"><label>Tierart<input name="species" required maxLength={80} placeholder="Katze" /></label><label>Rasse<input name="breed" maxLength={120} /></label></div><div className="split"><label>Geburtsdatum<input name="birthDate" type="date" /></label><label>Geschlecht<select name="sex" defaultValue="unknown"><option value="unknown">Unbekannt</option><option value="female">Weiblich</option><option value="male">Männlich</option></select></label></div><label className="inline"><input name="approximateBirthDate" type="checkbox" />Geburtsdatum ist ungefähr</label><div className="split"><label>Farbe/Zeichnung<input name="color" maxLength={100} /></label><label>Chipnummer<input name="microchipNumber" minLength={5} maxLength={50} autoComplete="off" /></label></div><label>Stammtierarzt/Praxis<input name="veterinarian" maxLength={200} /></label><div className="split"><label>Versicherung<input name="insurance" maxLength={200} /></label><label>Versicherungsnummer<input name="insuranceNumber" maxLength={100} autoComplete="off" /></label></div><button className="primary" disabled={busy}>Tier speichern</button></form>
      <section className="card list-card"><div className="section-title"><h2>Tiere</h2><span>{pets.length}</span></div>{pets.length === 0 ? <div className="empty"><strong>Noch kein Tier angelegt</strong><p>Lege links das erste Haustier an.</p></div> : <ul className="pet-list">{pets.map((pet) => <PetRow key={pet.id} pet={pet} events={events} busy={busy} run={run} toggle={toggle} />)}</ul>}</section></div></>;
}

export function PetRow({ pet, events: _events=[], busy, run, toggle }: { pet: Pet;events?:CalendarEvent[]; busy: boolean; run: (task: () => Promise<unknown>, success: string) => Promise<void>; toggle: (pet: Pet) => Promise<void> }) {
  const [records, setRecords] = useState<MedicalRecord[] | null>(null); const [error, setError] = useState("");
  const [vaccinations, setVaccinations] = useState<Vaccination[] | null>(null); const [vaccinationError, setVaccinationError] = useState("");
  const [medications,setMedications]=useState<PetMedication[]|null>(null);const[medicationError,setMedicationError]=useState("");
  const [restockPreview,setRestockPreview]=useState<MedicationRestockPreview|null>(null);
  const [documents,setDocuments]=useState<PetDocument[]|null>(null);const[documentError,setDocumentError]=useState("");
  const [weights,setWeights]=useState<WeightEntry[]|null>(null);const[weightError,setWeightError]=useState("");
  const [labs,setLabs]=useState<LabResult[]|null>(null);const[labError,setLabError]=useState("");
  const [dashboard,setDashboard]=useState<PetDashboard|null>(null);const[dashboardError,setDashboardError]=useState("");
  const [timeline,setTimeline]=useState<PetTimelineItem[]|null>(null);const[timelineCursor,setTimelineCursor]=useState("");const[timelineError,setTimelineError]=useState("");
  async function loadRecords() { try { setRecords((await api.medicalRecords(pet.id)).records); setError(""); } catch (reason) { setError(reason instanceof Error ? reason.message : "Akte konnte nicht geladen werden"); } }
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = event.currentTarget; const data = new FormData(form);
    await run(() => api.addMedicalRecord(pet.id, { recordType: String(data.get("recordType")) as MedicalRecordType, occurredOn: String(data.get("occurredOn")), title: String(data.get("title")), summary: String(data.get("summary")), veterinarian: String(data.get("veterinarian")), details: {} }), "Akteneintrag gespeichert"); form.reset(); await loadRecords();
  }
  async function loadVaccinations() { try { setVaccinations((await api.vaccinations(pet.id)).vaccinations); setVaccinationError(""); } catch (reason) { setVaccinationError(reason instanceof Error ? reason.message : "Impfungen konnten nicht geladen werden"); } }
  async function submitVaccination(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form=event.currentTarget;const data=new FormData(form);await run(()=>api.addVaccination(pet.id,{vaccineName:String(data.get("vaccineName")),manufacturer:String(data.get("manufacturer")),diseases:String(data.get("diseases")).split(",").map((value)=>value.trim()).filter(Boolean),administeredOn:String(data.get("administeredOn")),validUntil:String(data.get("validUntil"))||undefined,nextDueDate:String(data.get("nextDueDate"))||undefined,documentId:String(data.get("documentId"))||undefined,veterinarian:String(data.get("veterinarian")),batchNumber:String(data.get("batchNumber")),notes:""}),"Impfung dokumentiert");form.reset();await loadVaccinations(); }
  async function loadMedications(){try{setMedications((await api.petMedications(pet.id)).medications);setMedicationError("")}catch(reason){setMedicationError(reason instanceof Error?reason.message:"Medikamente konnten nicht geladen werden")}}
  async function submitMedication(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);const optional=(name:string)=>String(data.get(name))||undefined;await run(()=>api.addPetMedication(pet.id,{name:String(data.get("name")),activeIngredient:String(data.get("activeIngredient")),dosageForm:String(data.get("dosageForm")),doseText:String(data.get("doseText")),frequencyText:String(data.get("frequencyText")),startsOn:String(data.get("startsOn")),stockQuantity:String(data.get("stockQuantity")),stockUnit:String(data.get("stockUnit")),packageSize:optional("packageSize"),minimumStock:optional("minimumStock"),purchasedOn:optional("purchasedOn"),expiresOn:optional("expiresOn"),notes:""}),"Medikament dokumentiert");form.reset();await loadMedications()}
  async function previewRestock(medicationId:string){try{setRestockPreview(await api.medicationRestockPreview(pet.id,medicationId));setMedicationError("")}catch(reason){setMedicationError(reason instanceof Error?reason.message:"Einkaufsvorschau konnte nicht geladen werden")}}
  async function confirmRestock(){if(!restockPreview)return;await run(()=>api.createMedicationShoppingItem(pet.id,restockPreview.medicationId,"shared"),"Medikament auf Einkaufsliste gesetzt");setRestockPreview(null)}
  async function updateStock(event:FormEvent<HTMLFormElement>,medicationId:string){event.preventDefault();const value=String(new FormData(event.currentTarget).get("stockQuantity"));await run(()=>api.updateMedicationStock(pet.id,medicationId,value),"Bestand aktualisiert");await loadMedications()}
  async function loadDocuments(){try{setDocuments((await api.petDocuments(pet.id)).documents);setDocumentError("")}catch(reason){setDocumentError(reason instanceof Error?reason.message:"Dokumente konnten nicht geladen werden")}}
  async function uploadDocument(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);await run(()=>api.uploadPetDocument(pet.id,data),"Medizinisches Dokument sicher gespeichert");form.reset();await loadDocuments()}
  async function loadWeights(){try{setWeights((await api.petWeights(pet.id)).weights);setWeightError("")}catch(reason){setWeightError(reason instanceof Error?reason.message:"Gewichte konnten nicht geladen werden")}}
  async function submitWeight(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);await run(()=>api.addPetWeight(pet.id,{measuredOn:String(data.get("measuredOn")),weightKg:String(data.get("weightKg")),notes:String(data.get("notes"))}),"Gewicht dokumentiert");form.reset();await loadWeights()}
  async function loadLabs(){try{setLabs((await api.petLabResults(pet.id)).labResults);setLabError("")}catch(reason){setLabError(reason instanceof Error?reason.message:"Laborwerte konnten nicht geladen werden")}}
  async function submitLab(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);const low=String(data.get("referenceLow")??"");const high=String(data.get("referenceHigh")??"");await run(()=>api.addPetLabResult(pet.id,{measuredOn:String(data.get("measuredOn")),testName:String(data.get("testName")),value:String(data.get("value")),unit:String(data.get("unit")),referenceLow:low||undefined,referenceHigh:high||undefined,notes:""}),"Laborwert dokumentiert");form.reset();await loadLabs()}
  async function loadDashboard(){try{setDashboard(await api.petDashboard(pet.id,currentMonth()));setDashboardError("")}catch(reason){setDashboardError(reason instanceof Error?reason.message:"Übersicht konnte nicht geladen werden")}}
  async function loadTimeline(cursor=""){try{const page=await api.petTimeline(pet.id,cursor);setTimeline((current)=>cursor&&current?[...current,...page.items]:page.items);setTimelineCursor(page.nextCursor??"");setTimelineError("")}catch(reason){setTimelineError(reason instanceof Error?reason.message:"Zeitleiste konnte nicht geladen werden")}}
  return <li className={!pet.active ? "inactive" : ""}><div className="pet-head"><div><strong>{pet.name}</strong><small>{pet.species}{pet.breed && ` · ${pet.breed}`}{pet.color && ` · ${pet.color}`}{pet.birthDate && ` · ${pet.approximateBirthDate ? "ca. " : ""}geboren ${pet.birthDate}`}</small>{(pet.veterinarian || pet.insurance) && <small>{pet.veterinarian && `Praxis: ${pet.veterinarian}`}{pet.veterinarian && pet.insurance && " · "}{pet.insurance && `Versicherung: ${pet.insurance}${pet.insuranceNumber ? ` (${pet.insuranceNumber})` : ""}`}</small>}</div><button disabled={busy} onClick={() => void toggle(pet)}>{pet.active ? "Archivieren" : "Aktivieren"}</button></div>
    <details onToggle={(event)=>{if(event.currentTarget.open&&dashboard===null)void loadDashboard()}}><summary>Übersicht</summary>{dashboardError&&<div className="error" role="alert">{dashboardError}</div>}{dashboard&&<div className="dashboard-grid"><article><strong>{dashboard.activeMedicationCount}</strong><small>aktive Medikamente</small></article><article><strong>{dashboard.openShoppingItemCount}</strong><small>offene Einkäufe</small></article><article><strong>{dashboard.documentCount}</strong><small>Dokumente</small></article><article><strong>{dashboard.latestWeightKg?`${dashboard.latestWeightKg} kg`:"–"}</strong><small>letztes Gewicht</small></article><article><strong>{euros(dashboard.plannedAmountCents)}</strong><small>geplant im Monat</small></article><article><strong>{euros(dashboard.budgetAmountCents)}</strong><small>Monatsbudget</small></article>{dashboard.nextAppointmentTitle&&<article><strong>{dashboard.nextAppointmentTitle}</strong><small>nächster Termin</small></article>}{dashboard.nextVaccinationName&&<article><strong>{dashboard.nextVaccinationName}</strong><small>nächste Impffälligkeit {dashboard.nextVaccinationDate}</small></article>}</div>}</details>
    <details onToggle={(event)=>{if(event.currentTarget.open&&timeline===null)void loadTimeline()}}><summary>Gesamtzeitleiste</summary>{timelineError&&<div className="error" role="alert">{timelineError}</div>}{timeline&&(timeline.length===0?<p className="no-receipts">Noch keine Ereignisse dokumentiert.</p>:<><ol className="medical-list">{timeline.map((item)=><li key={`${item.type}-${item.sourceId}`}><time>{item.date}</time><div><strong>{item.title}</strong><small>{timelineTypeLabel(item.type)}</small></div></li>)}</ol>{timelineCursor&&<button disabled={busy} onClick={()=>void loadTimeline(timelineCursor)}>Weitere laden</button>}</>)}</details>
    <details onToggle={(event) => { if (event.currentTarget.open && records === null) void loadRecords(); }}><summary>Patientenakte</summary>{error && <div className="error" role="alert">{error}</div>}
      {records && (records.length === 0 ? <p className="no-receipts">Noch keine Einträge.</p> : <ol className="medical-list">{records.map((record) => <li key={record.id}><time>{record.occurredOn}</time><div><strong>{record.title}</strong><small>{recordTypeLabel(record.recordType)}{record.veterinarian && ` · ${record.veterinarian}`}</small>{record.summary && <p>{record.summary}</p>}</div></li>)}</ol>)}
      <form className="medical-form" onSubmit={submit}><div className="split"><label>Datum<input name="occurredOn" type="date" required max={new Date().toISOString().slice(0, 10)} /></label><label>Art<select name="recordType" defaultValue="examination"><option value="examination">Untersuchung</option><option value="diagnosis">Diagnose (dokumentiert)</option><option value="treatment">Behandlung</option><option value="procedure">Eingriff</option><option value="note">Notiz</option><option value="imaging">Bildgebung</option><option value="report">Bericht</option></select></label></div><label>Titel<input name="title" required maxLength={200} /></label><label>Tierarzt/Praxis<input name="veterinarian" maxLength={200} /></label><label>Dokumentation<textarea name="summary" maxLength={4000} /></label><button disabled={busy}>Eintrag speichern</button><small>HomeFlow dokumentiert nur und gibt keine Diagnose- oder Behandlungsempfehlungen.</small></form>
    </details>
    <details onToggle={(event)=>{if(event.currentTarget.open){if(vaccinations===null)void loadVaccinations();if(documents===null)void loadDocuments();}}}><summary>Impfungen</summary>{vaccinationError&&<div className="error" role="alert">{vaccinationError}</div>}{vaccinations&&(vaccinations.length===0?<p className="no-receipts">Noch keine Impfungen dokumentiert.</p>:<ol className="medical-list">{vaccinations.map((item)=><li key={item.id}><time>{item.administeredOn}</time><div><strong>{item.vaccineName}{item.manufacturer&&` · ${item.manufacturer}`}</strong><small>{item.diseases.length>0&&`${item.diseases.join(", ")} · `}{item.nextDueDate?`Nächste Fälligkeit: ${item.nextDueDate}`:"Keine nächste Fälligkeit hinterlegt"}{item.validUntil&&` · gültig bis ${item.validUntil}`}{item.veterinarian&&` · ${item.veterinarian}`}</small></div></li>)}</ol>)}<form className="medical-form" onSubmit={submitVaccination}><div className="split"><label>Impfdatum<input name="administeredOn" type="date" required max={new Date().toISOString().slice(0,10)}/></label><label>Gültig bis<input name="validUntil" type="date"/></label></div><div className="split"><label>Nächste Fälligkeit<input name="nextDueDate" type="date"/></label><label>Dokument<select name="documentId" defaultValue=""><option value="">Kein Dokument</option>{documents?.map((item)=><option key={item.id} value={item.id}>{item.title}</option>)}</select></label></div><label>Impfstoff<input name="vaccineName" required maxLength={200}/></label><div className="split"><label>Hersteller<input name="manufacturer" maxLength={200}/></label><label>Krankheiten, kommasepariert<input name="diseases" maxLength={500}/></label></div><div className="split"><label>Tierarzt/Praxis<input name="veterinarian" maxLength={200}/></label><label>Chargennummer<input name="batchNumber" maxLength={100}/></label></div><button disabled={busy}>Impfung speichern</button><small>Alle Datumsangaben werden manuell eingetragen; HomeFlow berechnet keine Impfintervalle.</small></form></details>
    <details onToggle={(event)=>{if(event.currentTarget.open&&medications===null)void loadMedications()}}><summary>Medikamente</summary>{medicationError&&<div className="error" role="alert">{medicationError}</div>}{medications&&(medications.length===0?<p className="no-receipts">Noch keine Medikamente dokumentiert.</p>:<ol className="medical-list">{medications.map((item)=><li key={item.id}><time>{item.startsOn}</time><div><strong>{item.name}</strong><small>{item.doseText} · {item.frequencyText} · Bestand {item.stockQuantity} {item.stockUnit}{item.minimumStock&&` · Mindestbestand ${item.minimumStock}`}{item.expiresOn&&` · haltbar bis ${item.expiresOn}`}</small><form className="split" onSubmit={(event)=>void updateStock(event,item.id)}><label>Neuer Bestand<input name="stockQuantity" required defaultValue={item.stockQuantity} pattern="[0-9]+([.][0-9]{1,3})?"/></label><button disabled={busy}>Bestand speichern</button></form>{item.minimumStock&&Number(item.stockQuantity)<Number(item.minimumStock)&&<button disabled={busy} onClick={()=>void previewRestock(item.id)}>Einkauf prüfen</button>}</div></li>)}</ol>)}{restockPreview&&<div className="notice"><strong>Vorschau: {restockPreview.name}</strong><p>Bestand {restockPreview.stockQuantity} von mindestens {restockPreview.minimumStock} {restockPreview.stockUnit}. Es wird genau ein offener Artikel angelegt.</p><button disabled={busy} onClick={()=>void confirmRestock()}>Jetzt auf Einkaufsliste setzen</button><button disabled={busy} onClick={()=>setRestockPreview(null)}>Abbrechen</button></div>}<form className="medical-form" onSubmit={submitMedication}><label>Medikament<input name="name" required maxLength={200}/></label><div className="split"><label>Wirkstoff<input name="activeIngredient" maxLength={200}/></label><label>Form<input name="dosageForm" maxLength={100}/></label></div><div className="split"><label>Dokumentierte Dosis<input name="doseText" required maxLength={200}/></label><label>Dokumentierte Häufigkeit<input name="frequencyText" required maxLength={200}/></label></div><label>Beginn<input name="startsOn" type="date" required/></label><div className="split"><label>Bestand<input name="stockQuantity" required pattern="[0-9]+([.][0-9]{1,3})?" defaultValue="0"/></label><label>Einheit<input name="stockUnit" maxLength={50}/></label></div><div className="split"><label>Packungsgröße<input name="packageSize" pattern="[0-9]+([.][0-9]{1,3})?"/></label><label>Mindestbestand<input name="minimumStock" pattern="[0-9]+([.][0-9]{1,3})?"/></label></div><div className="split"><label>Gekauft am<input name="purchasedOn" type="date"/></label><label>Haltbar bis<input name="expiresOn" type="date"/></label></div><button disabled={busy}>Medikament speichern</button><small>Alle Bestandswerte verwenden dieselbe Einheit. HomeFlow berechnet weder Dosis noch Verbrauch.</small></form></details>
    <details onToggle={(event)=>{if(event.currentTarget.open&&weights===null)void loadWeights()}}><summary>Gewichtsverlauf</summary>{weightError&&<div className="error" role="alert">{weightError}</div>}{weights&&(weights.length===0?<p className="no-receipts">Noch kein Gewicht dokumentiert.</p>:<ol className="medical-list">{weights.map((item)=><li key={item.id}><time>{item.measuredOn}</time><div><strong>{item.weightKg} kg</strong>{item.notes&&<small>{item.notes}</small>}</div></li>)}</ol>)}<form className="medical-form" onSubmit={submitWeight}><div className="split"><label>Datum<input name="measuredOn" type="date" required max={new Date().toISOString().slice(0,10)}/></label><label>Gewicht in kg<input name="weightKg" required inputMode="decimal" pattern="(0\.[0-9]{1,3}|[1-9][0-9]{0,6}(\.[0-9]{1,3})?)" placeholder="4.250"/></label></div><label>Notiz<input name="notes" maxLength={1000}/></label><button disabled={busy}>Gewicht speichern</button></form></details>
    <details onToggle={(event)=>{if(event.currentTarget.open&&labs===null)void loadLabs()}}><summary>Laborwerte</summary>{labError&&<div className="error" role="alert">{labError}</div>}{labs&&(labs.length===0?<p className="no-receipts">Noch keine Laborwerte dokumentiert.</p>:<ol className="medical-list">{labs.map((item)=><li key={item.id}><time>{item.measuredOn}</time><div><strong>{item.testName}: {item.value} {item.unit}</strong><small>{item.referenceLow||item.referenceHigh?`Dokumentierter Referenzbereich ${item.referenceLow??"–"} bis ${item.referenceHigh??"–"}`:"Kein Referenzbereich hinterlegt"}</small></div></li>)}</ol>)}<form className="medical-form" onSubmit={submitLab}><div className="split"><label>Datum<input name="measuredOn" type="date" required max={new Date().toISOString().slice(0,10)}/></label><label>Untersuchung<input name="testName" required maxLength={200}/></label></div><div className="split"><label>Wert<input name="value" required inputMode="decimal"/></label><label>Einheit<input name="unit" maxLength={50}/></label></div><div className="split"><label>Referenz von<input name="referenceLow" inputMode="decimal"/></label><label>Referenz bis<input name="referenceHigh" inputMode="decimal"/></label></div><button disabled={busy}>Laborwert speichern</button><small>HomeFlow speichert diese Werte nur und bewertet sie medizinisch nicht.</small></form></details>
    <details onToggle={(event)=>{if(event.currentTarget.open&&documents===null)void loadDocuments()}}><summary>Medizinische Dokumente</summary>{documentError&&<div className="error" role="alert">{documentError}</div>}{documents&&(documents.length===0?<p className="no-receipts">Noch keine Dokumente gespeichert.</p>:<ul className="document-list">{documents.map((item)=><li key={item.id}><a href={petDocumentContentPath(pet.id,item.id)} rel="noopener">{item.title}</a><small>{item.occurredOn??item.uploadedAt.slice(0,10)} · {documentTypeLabel(item.documentType)} · {item.originalFilename}</small><RelationshipEditor kind="document" sourceId={item.id} petId={pet.id} events={_events} busy={busy} run={run}/></li>)}</ul>)}<form className="medical-form" onSubmit={uploadDocument}><label>Datei<input name="file" type="file" accept="image/jpeg,image/png,application/pdf" required/></label><div className="split"><label>Titel<input name="title" required maxLength={200}/></label><label>Art<select name="documentType" defaultValue="report"><option value="report">Befund/Bericht</option><option value="lab">Labor</option><option value="vaccination">Impfnachweis</option><option value="imaging">Bildgebung</option><option value="insurance">Versicherung</option><option value="other">Sonstiges</option></select></label></div><label>Dokumentdatum<input name="occurredOn" type="date" max={new Date().toISOString().slice(0,10)}/></label><label>Notizen<textarea name="notes" maxLength={2000}/></label><button disabled={busy}>Dokument lokal speichern</button><small>JPEG, PNG oder PDF bis 10 MiB. Downloads werden nie direkt im Browser ausgeführt.</small></form></details></li>;
}

function recordTypeLabel(type: MedicalRecordType) { return ({ diagnosis: "Diagnose", treatment: "Behandlung", procedure: "Eingriff", examination: "Untersuchung", note: "Notiz", imaging: "Bildgebung", report: "Bericht" })[type]; }
function documentTypeLabel(type: PetDocument["documentType"]) { return ({ report: "Befund/Bericht", lab: "Labor", vaccination: "Impfnachweis", imaging: "Bildgebung", insurance: "Versicherung", other: "Sonstiges" })[type]; }
function timelineTypeLabel(type: PetTimelineItem["type"]){return({medical_record:"Patientenakte",vaccination:"Impfung",medication:"Medikament",weight:"Gewicht",lab_result:"Laborwert",document:"Dokument",appointment:"Tiertermin"})[type]}

export function Login({ onSuccess }: { onSuccess: () => void }) {
  const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setBusy(true); setError("");
    const data = new FormData(event.currentTarget);
    try { await api.login(String(data.get("username")), String(data.get("password"))); onSuccess(); }
    catch (reason) { setError(reason instanceof Error ? reason.message : "Anmeldung fehlgeschlagen"); }
    finally { setBusy(false); }
  }
  return <main className="login-page">
    <section className="login-copy"><div className="brand large"><span>H</span> HomeFlow</div><p className="eyebrow">Euer Zuhause. Ein gemeinsamer Ort.</p><h1>Weniger organisieren.<br />Mehr zusammen leben.</h1><p>Einkäufe, Ausgaben und Belege sicher auf eurem eigenen Gerät verwalten.</p><div className="privacy">● Lokal betrieben &nbsp; ● Keine öffentliche Registrierung</div></section>
    <form className="card login-card" onSubmit={submit}><h2>Willkommen zurück</h2><p>Melde dich mit deinem HomeFlow-Konto an.</p><label>Benutzername<input name="username" autoComplete="username" required autoFocus /></label><label>Passwort<input name="password" type="password" autoComplete="current-password" required /></label>{error && <div className="error" role="alert">{error}</div>}<button className="primary" disabled={busy}>{busy ? "Anmeldung läuft …" : "Anmelden"}</button></form>
  </main>;
}

export function Shopping({ items,lists,pets, busy, run }: { items: ShoppingItem[];lists:ShoppingList[];pets:Pet[]; busy: boolean; run: (task: () => Promise<unknown>, success: string) => Promise<void> }) {
  const [forAllPets,setForAllPets]=useState(false);
  const open = items.filter((item) => !item.completed); const done = items.filter((item) => item.completed);
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = event.currentTarget; const data = new FormData(form);
    const price=String(data.get("estimatedPrice")??"");const estimatedPriceCents=price?centsFromAmountInput(price):undefined;if(price&&estimatedPriceCents===null)throw new Error("Schätzpreis bitte mit höchstens zwei Nachkommastellen eingeben");const all=data.get("forAllPets")==="on";const petIds=all?[]:data.getAll("petIds").map(String);if(!all&&petIds.length===0)throw new Error("Bitte mindestens ein Tier oder alle Tiere auswählen");await run(() => api.addShopping({ listId: String(data.get("listId")), name: String(data.get("name")), quantity: String(data.get("quantity")), unit: String(data.get("unit")), category: String(data.get("category")), priority: String(data.get("priority")), note: "", store: String(data.get("store")),petIds,forAllPets:all,preferredBrand:String(data.get("preferredBrand")),estimatedPriceCents:estimatedPriceCents??undefined,estimatedPriceCurrency:"EUR",recurring:data.get("recurring")==="on" }), "Artikel hinzugefügt"); form.reset();setForAllPets(false);
  }
  return <><section className="hero"><div><p className="eyebrow">Gemeinsame Liste</p><h1>Einkaufsliste</h1><p>{open.length} {open.length === 1 ? "Artikel ist" : "Artikel sind"} noch offen.</p></div><div className="hero-stat"><strong>{open.length}</strong><span>offen</span></div></section>
    <div className="layout"><form className="card form-card" onSubmit={submit}><h2>Artikel hinzufügen</h2><label>Liste<select name="listId" required>{lists.map((list)=><option key={list.id} value={list.id}>{list.name}</option>)}</select></label><label>Was braucht ihr?<input name="name" required maxLength={120} placeholder="z. B. Futter" /></label><div className="split"><label>Menge<input name="quantity" required defaultValue="1" /></label><label>Einheit<select name="unit" defaultValue="Stück"><option>Stück</option><option>Packung</option><option>Liter</option><option>kg</option></select></label></div><label>Kategorie<input name="category" placeholder="Futter" /></label><div className="split"><label>Bevorzugte Marke<input name="preferredBrand" maxLength={200}/></label><label>Laden<input name="store"/></label></div><div className="split"><label>Schätzpreis in €<input name="estimatedPrice" type="number" min="0" step="0.01"/></label><label className="inline"><input name="recurring" type="checkbox"/>Wiederkehrend dokumentieren</label></div><label>Priorität<select name="priority" defaultValue="normal"><option value="low">Niedrig</option><option value="normal">Normal</option><option value="high">Hoch</option></select></label><fieldset><legend>Für welche Tiere?</legend><label className="inline"><input name="forAllPets" type="checkbox" checked={forAllPets} onChange={(event)=>setForAllPets(event.target.checked)}/>Alle Tiere</label>{pets.map((pet)=><label className="inline" key={pet.id}><input type="checkbox" name="petIds" value={pet.id} disabled={forAllPets}/>{pet.name}</label>)}</fieldset><button className="primary" disabled={busy||lists.length===0||pets.length===0}>Zur Liste hinzufügen</button></form>
      <section className="card list-card"><div className="section-title"><h2>Offene Artikel</h2><span>{open.length}</span></div>{open.length === 0 ? <div className="empty"><strong>Alles erledigt</strong><p>Für eure Tiere ist gerade nichts offen.</p></div> : <ul className="item-list">{open.map((item) => <li key={item.id}><button className="check" aria-label={`${item.name} erledigen`} disabled={busy} onClick={() => void run(() => api.completeShopping(item.id), `${item.name} erledigt`)}>✓</button><div><strong>{item.name}</strong><small>{item.quantity} {item.unit} {item.category && `· ${item.category}`}{item.preferredBrand&&` · ${item.preferredBrand}`}{item.estimatedPriceCents!==undefined&&` · ca. ${euros(item.estimatedPriceCents)}`}{item.recurring&&" · wiederkehrend"}{item.forAllPets?" · alle Tiere":item.petIds?.length>0&&` · ${item.petIds.map((id)=>pets.find((pet)=>pet.id===id)?.name??"Tier").join(", ")}`}</small></div>{item.priority === "high" && <span className="tag">Wichtig</span>}</li>)}</ul>}{done.length > 0 && <details><summary>Erledigt ({done.length})</summary><ul className="done-list">{done.map((item) => <li key={item.id}>{item.name}</li>)}</ul></details>}</section></div></>;
}

export function Expenses({ items, summary, pets, events, month, setMonth, busy, run }: { items: Expense[]; summary: ExpenseSummary | null; pets:Pet[];events:CalendarEvent[]; month: string; setMonth: (month: string) => void; busy: boolean; run: (task: () => Promise<unknown>, success: string) => Promise<void> }) {
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; const d = new FormData(form); const petId=String(d.get("petId")??""); await run(() => api.addExpense({ description: String(d.get("description")), merchant: String(d.get("merchant")), plannedAmountCents: Math.round(Number(d.get("amount")) * 100), currency: "EUR", dueDate: String(d.get("dueDate")), category: String(d.get("category")), recurrenceRule: "", status: "planned", paymentMethod: "", notes: "",petId,budgetCategory:String(d.get("budgetCategory")) }), "Ausgabe gespeichert"); form.reset(); }
  return <><section className="hero"><div><p className="eyebrow">Haushaltsübersicht</p><h1>Geplante Ausgaben</h1><label className="month">Monat <input type="month" value={month} onChange={(e) => setMonth(e.target.value)} /></label></div></section>
    <section className="stats"><article><span>Geplant</span><strong>{euros(summary?.plannedAmountCents ?? 0)}</strong></article><article><span>Tatsächlich</span><strong>{euros(summary?.actualAmountCents ?? 0)}</strong></article><article><span>Noch offen</span><strong>{euros(summary?.openAmountCents ?? 0)}</strong></article></section>
    <div className="layout"><form className="card form-card" onSubmit={submit}><h2>Ausgabe planen</h2><label>Beschreibung<input name="description" required placeholder="z. B. Untersuchung" /></label><label>Händler<input name="merchant" /></label><div className="split"><label>Betrag in €<input name="amount" type="number" min="0.01" step="0.01" required /></label><label>Fällig am<input name="dueDate" type="date" required /></label></div><label>Kategorie<input name="category" placeholder="Tiergesundheit" /></label><div className="split"><label>Tier<select name="petId" defaultValue="" required><option value="" disabled>Tier auswählen</option>{pets.map((pet)=><option key={pet.id} value={pet.id}>{pet.name}</option>)}</select></label><label>Budgetkategorie<input name="budgetCategory" maxLength={100} placeholder="z. B. Tierarzt" /></label></div><button className="primary" disabled={busy||pets.length===0}>Ausgabe speichern</button></form>
      <section className="card list-card"><div className="section-title"><h2>Ausgaben</h2><span>{items.length}</span></div>{items.length === 0 ? <div className="empty"><strong>Noch keine Ausgaben</strong><p>Plane links eure erste Haushaltsausgabe.</p></div> : <ul className="expense-list">{items.map((expense) => <ExpenseRow key={expense.id} expense={expense} pet={pets.find((pet)=>pet.id===expense.petId)} events={events.filter((event)=>event.petId===expense.petId)} busy={busy} run={run} />)}</ul>}</section></div>
    {pets.length>0&&<PetFinance pets={pets} month={month} busy={busy} run={run}/>}</>;
}

export function ExpenseRow({ expense, pet, events: _events=[], busy, run }: { expense: Expense; pet?:Pet;events?:CalendarEvent[]; busy: boolean; run: (task: () => Promise<unknown>, success: string) => Promise<void> }) {
  const deviates = expense.actualAmountCents !== undefined && expense.actualAmountCents !== expense.plannedAmountCents;
  const [receipts, setReceipts] = useState<Receipt[] | null>(null);
  const [receiptError, setReceiptError] = useState("");
  const loadReceipts = useCallback(async () => {
    try { setReceipts((await api.receipts(expense.id)).receipts); setReceiptError(""); }
    catch (error) { setReceiptError(error instanceof Error ? error.message : "Belege konnten nicht geladen werden"); }
  }, [expense.id]);
  async function upload(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; const data = new FormData(form); await run(() => api.uploadReceipt(expense.id, data), "Beleg sicher gespeichert"); form.reset(); await loadReceipts(); }
  async function pay(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const entered = String(new FormData(event.currentTarget).get("actualAmount") ?? "");
    await run(async () => {
      const cents = centsFromAmountInput(entered);
      if (cents === null) throw new Error("Ist-Betrag bitte als Zahl mit höchstens zwei Nachkommastellen eingeben, z. B. 42,90");
      await api.payExpense(expense.id, cents);
    }, "Ausgabe als bezahlt markiert");
  }
  return <li><div className="expense-main"><div><strong>{expense.description}</strong><small>{expense.dueDate} {expense.category && `· ${expense.category}`}{pet&&` · ${pet.name}`}{expense.budgetCategory&&` · Budget: ${expense.budgetCategory}`}{deviates && ` · geplant ${euros(expense.plannedAmountCents)}`}</small></div><b>{euros(expense.actualAmountCents ?? expense.plannedAmountCents)}</b></div><div className="row-actions"><span className={`status ${expense.status}`}>{expense.status === "paid" ? "Bezahlt" : "Offen"}</span>{expense.status !== "paid" && <form className="pay" onSubmit={pay}><label>Ist-Betrag in €<input name="actualAmount" type="number" min="0" step="0.01" required defaultValue={amountInputValue(expense.plannedAmountCents)} aria-label={`Tatsächlich gezahlter Betrag für ${expense.description} in Euro`} /></label><button disabled={busy}>Als bezahlt markieren</button></form>}<details onToggle={(event) => { if (event.currentTarget.open && receipts === null) void loadReceipts(); }}><summary>Belege</summary>{receiptError && <div className="error" role="alert">{receiptError}</div>}{receipts !== null && (receipts.length === 0 ? <p className="no-receipts">Noch kein Beleg hinterlegt.</p> : <ul className="receipt-list">{receipts.map((receipt) => <li key={receipt.id}><a href={receiptContentPath(expense.id, receipt.id)} rel="noopener">{receipt.originalFilename}</a><small>{receipt.uploadedAt.slice(0, 10)} · {receipt.mimeType}</small></li>)}</ul>)}<form className="upload" onSubmit={upload}><input name="file" type="file" accept="image/jpeg,image/png,application/pdf" required /><input type="hidden" name="currency" value="EUR" /><button disabled={busy}>Hochladen</button></form></details>{pet&&<RelationshipEditor kind="expense" sourceId={expense.id} petId={pet.id} events={_events} busy={busy} run={run}/>}</div></li>;
}

function RelationshipEditor({kind,sourceId,petId,events,busy,run}:{kind:"expense"|"document";sourceId:string;petId:string;events:CalendarEvent[];busy:boolean;run:(task:()=>Promise<unknown>,success:string)=>Promise<void>}){
  const[records,setRecords]=useState<MedicalRecord[]|null>(null);const[links,setLinks]=useState<RelationshipSet|null>(null);const[error,setError]=useState("");
  async function load(){try{const[recordPage,current]=await Promise.all([api.medicalRecords(petId),kind==="expense"?api.expenseLinks(sourceId):api.documentLinks(petId,sourceId)]);setRecords(recordPage.records);setLinks(current);setError("")}catch(reason){setError(reason instanceof Error?reason.message:"Verknüpfungen konnten nicht geladen werden")}}
  async function save(event:FormEvent<HTMLFormElement>){event.preventDefault();const data=new FormData(event.currentTarget);const input={medicalRecordIds:data.getAll("medicalRecordIds").map(String),appointmentIds:data.getAll("appointmentIds").map(String)};await run(()=>kind==="expense"?api.saveExpenseLinks(sourceId,input):api.saveDocumentLinks(petId,sourceId,input),"Verknüpfungen gespeichert");setLinks(input)}
  return <details className="relationships" onToggle={(event)=>{if(event.currentTarget.open&&links===null)void load()}}><summary>Patientenakte und Termin zuordnen</summary>{error&&<div className="error" role="alert">{error}</div>}{links&&<form onSubmit={save}><fieldset><legend>Akteneinträge</legend>{records?.length?<>{records.map((record)=><label className="inline" key={record.id}><input type="checkbox" name="medicalRecordIds" value={record.id} defaultChecked={links.medicalRecordIds.includes(record.id)}/>{record.occurredOn} · {record.title}</label>)}</>:<small>Keine Akteneinträge vorhanden.</small>}</fieldset><fieldset><legend>Tiertermine</legend>{events.length?<>{events.map((item)=><label className="inline" key={item.id}><input type="checkbox" name="appointmentIds" value={item.id} defaultChecked={links.appointmentIds.includes(item.id)}/>{item.startsAt.slice(0,10)} · {item.title}</label>)}</>:<small>Keine Termine im geladenen Zeitraum.</small>}</fieldset><button disabled={busy}>Zuordnung speichern</button></form>}</details>
}

function PetFinance({pets,month,busy,run}:{pets:Pet[];month:string;busy:boolean;run:(task:()=>Promise<unknown>,success:string)=>Promise<void>}){
  const [petId,setPetId]=useState(pets[0]?.id??"");const [budgets,setBudgets]=useState<PetBudget[]>([]);const [summary,setSummary]=useState<PetExpenseSummary|null>(null);const [error,setError]=useState("");
  const loadFinance=useCallback(async()=>{if(!petId)return;try{const [b,s]=await Promise.all([api.petBudgets(petId,month),api.petExpenseSummary(petId,month)]);setBudgets(b.budgets);setSummary(s);setError("")}catch(reason){setError(reason instanceof Error?reason.message:"Tierfinanzen konnten nicht geladen werden")}},[petId,month]);
  useEffect(()=>{void loadFinance()},[loadFinance]);
  async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const data=new FormData(form);await run(async()=>{const cents=centsFromAmountInput(String(data.get("amount")??""));const thresholdInput=String(data.get("warningThreshold")??"").trim();const warningThresholdCents=thresholdInput===""?undefined:centsFromAmountInput(thresholdInput);if(cents===null||warningThresholdCents===null)throw new Error("Beträge bitte mit höchstens zwei Nachkommastellen eingeben");await api.savePetBudget(petId,{month,category:String(data.get("category")),amountCents:cents,currency:"EUR",warningThresholdCents,notes:String(data.get("notes")??"")})},"Tierbudget gespeichert");form.reset();await loadFinance()}
  return <section className="card pet-finance"><div className="section-title"><h2>Tierbudgets</h2><label>Tier<select value={petId} onChange={(event)=>setPetId(event.target.value)}>{pets.map((pet)=><option key={pet.id} value={pet.id}>{pet.name}</option>)}</select></label></div>{error&&<div className="error" role="alert">{error}</div>}<form className="budget-form" onSubmit={submit}><label>Kategorie<input name="category" required maxLength={100} placeholder="Tierarzt"/></label><label>Monatsbudget in €<input name="amount" type="number" min="0" step="0.01" required/></label><label>Warnen ab Restbetrag in €<input name="warningThreshold" type="number" min="0" step="0.01" placeholder="optional"/></label><label>Notiz<input name="notes" maxLength={2000} placeholder="optional"/></label><button disabled={busy||!petId}>Speichern</button></form><div className="budget-grid">{(summary?.categories??[]).map((item)=><article key={item.category} className={item.warningThresholdReached?"warning":""}><strong>{item.category}</strong><small>Budget {euros(item.budgetAmountCents)} · geplant {euros(item.plannedAmountCents)} · tatsächlich {euros(item.actualAmountCents)} · verbleibend {euros(item.remainingBudgetCents)}</small>{item.warningThresholdReached&&<span className="status warning">Warnschwelle von {euros(item.warningThresholdCents??0)} erreicht</span>}</article>)}{budgets.length===0&&summary?.categories.length===0&&<p>Noch keine Tierbudgets oder Ausgaben in diesem Monat.</p>}</div><small>Auswertungen dokumentieren nur eure eigenen Eingaben; es gibt keine externen Finanz- oder Bezahldienste.</small></section>
}

export function Calendar({ events, pets, month, setMonth, busy, run }: { events: CalendarEvent[]; pets: Pet[]; month: string; setMonth: (month: string) => void; busy: boolean; run: (task: () => Promise<unknown>, success: string) => Promise<void> }) {
  const [allDay, setAllDay] = useState(false);
  const open = events.filter((event) => event.status === "planned");
  const days = groupByDay(events);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = event.currentTarget;
    const data = new FormData(form);
    const wholeDay = data.get("allDay") === "on";
    await run(async () => {
      const instants = eventInstants(String(data.get("startsAt") ?? ""), String(data.get("endsAt") ?? ""), wholeDay);
      if (instants === null) throw new Error("Bitte Beginn und Ende angeben — das Ende darf nicht vor dem Beginn liegen");
      const input: CalendarEventInput = {
        title: String(data.get("title")), description: "", allDay: wholeDay,
        category: String(data.get("category") ?? ""), visibility: data.get("visibility") === "on" ? "private" : "shared",
        recurrenceRule: "", status: "planned", ...instants,
      };
      input.petId=String(data.get("petId"));input.appointmentType=String(data.get("appointmentType")) as CalendarEvent["appointmentType"];
      await api.addCalendarEvent(input);
    }, "Termin gespeichert");
    form.reset(); setAllDay(false);
  }

  return <><section className="hero"><div><p className="eyebrow">Gemeinsame Termine</p><h1>Kalender</h1><label className="month">Monat <input type="month" value={month} onChange={(e) => setMonth(e.target.value)} /></label></div><div className="hero-stat"><strong>{open.length}</strong><span>geplant</span></div></section>
    <div className="layout"><form className="card form-card" onSubmit={submit}><h2>Termin anlegen</h2><label>Worum geht es?<input name="title" required maxLength={300} placeholder="z. B. Zahnarzt" /></label>
      <label className="inline"><input name="allDay" type="checkbox" checked={allDay} onChange={(e) => setAllDay(e.target.checked)} /> Ganztägig</label>
      <div className="split"><label>Beginn<input name="startsAt" type={allDay ? "date" : "datetime-local"} required /></label><label>Ende<input name="endsAt" type={allDay ? "date" : "datetime-local"} required /></label></div>
      <label>Kategorie<input name="category" maxLength={100} placeholder="Haushalt" /></label>
      <div className="split"><label>Tier<select name="petId" defaultValue="" required><option value="" disabled>Tier auswählen</option>{pets.map((pet)=><option key={pet.id} value={pet.id}>{pet.name}</option>)}</select></label><label>Terminart<select name="appointmentType" defaultValue="veterinarian"><option value="veterinarian">Tierarzt</option><option value="vaccination">Impfung</option><option value="medication">Medikament</option><option value="grooming">Pflege</option><option value="other">Sonstiges</option></select></label></div>
      <label className="inline"><input name="visibility" type="checkbox" /> Nur für mich</label>
      <button className="primary" disabled={busy||pets.length===0}>Termin speichern</button></form>
      <section className="card list-card"><div className="section-title"><h2>Termine</h2><span>{events.length}</span></div>
        {days.length === 0 ? <div className="empty"><strong>Nichts geplant</strong><p>In diesem Monat steht noch kein Termin an.</p></div> : days.map(([day, entries]) => <div className="day" key={day}><h3>{day}</h3><ul className="event-list">{entries.map((event) => <EventRow key={event.id} event={event} busy={busy} run={run} />)}</ul></div>)}
      </section></div></>;
}

// groupByDay keeps the order the API delivered - events arrive sorted by start
// instant - and only inserts a heading whenever the local day changes.
export function groupByDay(events: CalendarEvent[]): [string, CalendarEvent[]][] {
  const days: [string, CalendarEvent[]][] = [];
  for (const event of events) {
    const day = eventDay(event.startsAt);
    const last = days[days.length - 1];
    if (last && last[0] === day) last[1].push(event);
    else days.push([day, [event]]);
  }
  return days;
}

export function EventRow({ event, busy, run }: { event: CalendarEvent; busy: boolean; run: (task: () => Promise<unknown>, success: string) => Promise<void> }) {
  const period = event.allDay ? "Ganztägig" : `${eventClock(event.startsAt)} – ${eventClock(event.endsAt)}`;
  const spansDays = localInputValue(event.startsAt, true) !== localInputValue(event.endsAt, true);
  function replace(changes: Partial<CalendarEventInput>, success: string) {
    return run(() => api.updateCalendarEvent(event.id, {
      title: event.title, description: event.description ?? "", startsAt: event.startsAt, endsAt: event.endsAt,
      allDay: event.allDay, category: event.category ?? "", visibility: event.visibility,
      recurrenceRule: event.recurrenceRule ?? "", reminderMinutes: event.reminderMinutes,
      status: event.status, petId:event.petId, appointmentType:event.appointmentType, ...changes,
    }), success);
  }
  return <li><div className="event-main"><div><strong>{event.title}</strong><small>{period}{spansDays && ` · bis ${eventDay(event.endsAt)}`}{event.category && ` · ${event.category}`}{event.petId && ` · Tiertermin`}</small></div>{event.visibility === "private" && <span className="tag private">Privat</span>}</div>
    <div className="row-actions"><span className={`status ${event.status}`}>{event.status === "completed" ? "Erledigt" : event.status === "cancelled" ? "Abgesagt" : "Geplant"}</span>
      {event.status !== "completed" && <button disabled={busy} onClick={() => void replace({ status: "completed" }, "Termin als erledigt markiert")}>Erledigt</button>}
      {event.status === "completed" && <button disabled={busy} onClick={() => void replace({ status: "planned" }, "Termin wieder geöffnet")}>Wieder öffnen</button>}
      <button disabled={busy} onClick={() => void run(() => api.deleteCalendarEvent(event.id), "Termin gelöscht")}>Löschen</button></div></li>;
}
